contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 burnAmount) public {
        uint256 ownerBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        bool success;
        bool s = c.burn(burnAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            success = s;
            reverted = false;
        }

        uint256 ownerAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        assert(
            (reverted && ownerAfter == ownerBefore) ||
            (!reverted && success == true && burnAmount <= ownerBefore && ownerAfter == ownerBefore - burnAmount)
        );
    }
}

