pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 burnAmount) internal {
        uint256 ownerBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { ownerBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        bool reverted;
        bool success;
        try c.burn(burnAmount) returns (bool s) {
            success = s;
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 ownerAfter;
        try c.balanceOf(address(this)) returns (uint256 __r) { ownerAfter = __r; } catch { return; }
        assertTrue((reverted && ownerAfter == ownerBefore) ||
            (!reverted && success == true && burnAmount <= ownerBefore && ownerAfter == ownerBefore - burnAmount));
    }

    function testFuzz_run(uint256 burnAmount) public {
        _run(burnAmount);
    }

    receive() external payable {}
}
